// Raises the iOS deployment target of every CocoaPods target to a minimum (15.1 by default).
//
// Why: Xcode 27 refuses to build any target whose IPHONEOS_DEPLOYMENT_TARGET is below 15.0
// ("the range of supported deployment target versions is 15.0 to 27.0.x"). React Native's
// react_native_post_install raises each pod's main target, but not the resource-bundle
// targets that some pods add (RNCAsyncStorage_resources at 13.4, MapboxMapsResources at 14.0),
// so a Release build or Archive fails before anything compiles.
//
// ios/ is regenerated by `expo prebuild`, so the fix lives here instead of in ios/Podfile.
// The block is wrapped in begin/end markers and replaced on every run, so running prebuild
// again (with or without --clean) leaves exactly one copy.
const { withPodfile } = require('expo/config-plugins');

const BEGIN_MARKER = '# @generated begin holyguard-pod-deployment-target';
const END_MARKER = '# @generated end holyguard-pod-deployment-target';
const DEFAULT_MIN_TARGET = '15.1';

function buildBlock(minTarget) {
  return [
    `    ${BEGIN_MARKER} (managed by plugins/withPodDeploymentTarget.js, do not edit)`,
    `    # Xcode 27 rejects deployment targets below 15.0, including pod resource bundles.`,
    `    installer.pods_project.targets.each do |target|`,
    `      target.build_configurations.each do |build_config|`,
    `        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']`,
    `        next unless current.to_s.match?(/\\A\\d+(\\.\\d+)*\\z/)`,
    `        if Gem::Version.new(current) < Gem::Version.new('${minTarget}')`,
    `          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${minTarget}'`,
    `        end`,
    `      end`,
    `    end`,
    `    ${END_MARKER}`,
  ].join('\n');
}

// Removes a block written by an earlier run (marker lines included).
function removeExistingBlock(contents) {
  const lines = contents.split('\n');
  const out = [];
  let inside = false;
  for (const line of lines) {
    if (line.includes(BEGIN_MARKER)) {
      inside = true;
      continue;
    }
    if (inside) {
      if (line.includes(END_MARKER)) inside = false;
      continue;
    }
    out.push(line);
  }
  if (inside) {
    throw new Error(
      `[withPodDeploymentTarget] ios/Podfile has "${BEGIN_MARKER}" without a matching end marker. ` +
        'Fix the Podfile by hand or run `npx expo prebuild --clean`.'
    );
  }
  return out.join('\n');
}

// Returns the index just past the newline that ends the react_native_post_install(...) call,
// or -1 when the call is not in the Podfile.
function endOfReactNativePostInstall(contents) {
  const start = contents.indexOf('react_native_post_install(');
  if (start === -1) return -1;
  let depth = 0;
  for (let i = contents.indexOf('(', start); i < contents.length; i++) {
    const ch = contents[i];
    if (ch === '(') depth++;
    else if (ch === ')') {
      depth--;
      if (depth === 0) {
        const newline = contents.indexOf('\n', i);
        return newline === -1 ? contents.length : newline + 1;
      }
    }
  }
  return -1;
}

function addDeploymentTargetBlock(podfile, minTarget = DEFAULT_MIN_TARGET) {
  if (!/^\d+(\.\d+)*$/.test(String(minTarget))) {
    throw new Error(`[withPodDeploymentTarget] invalid deploymentTarget "${minTarget}"`);
  }
  const contents = removeExistingBlock(podfile);
  const block = buildBlock(minTarget) + '\n';

  let insertAt = endOfReactNativePostInstall(contents);
  if (insertAt === -1) {
    // Fallback: first line inside the post_install block.
    const match = contents.match(/^[ \t]*post_install do \|installer\|[^\n]*\n/m);
    if (!match) {
      throw new Error(
        '[withPodDeploymentTarget] could not find a post_install block in ios/Podfile; ' +
          'the Xcode 27 deployment-target fix was not applied.'
      );
    }
    insertAt = match.index + match[0].length;
  }
  return contents.slice(0, insertAt) + block + contents.slice(insertAt);
}

const withPodDeploymentTarget = (config, props = {}) =>
  withPodfile(config, (cfg) => {
    const minTarget = props.deploymentTarget || DEFAULT_MIN_TARGET;
    cfg.modResults.contents = addDeploymentTargetBlock(cfg.modResults.contents, minTarget);
    return cfg;
  });

module.exports = withPodDeploymentTarget;
module.exports.addDeploymentTargetBlock = addDeploymentTargetBlock;
